"undefined"!=typeof tinymce&&tinymce.PluginManager.add("jinyu_shortcodes",function(t){var n=(window.JINYU_SC&&window.JINYU_SC.list||[]).map(function(n){return{text:n.label,onclick:function(){t.insertContent(n.tpl)}}});t.addButton("jinyu_shortcodes",{text:"Jinyu Shortcodes",type:"menubutton",icon:!1,menu:n})});